INSERT INTO dump_descriptions (base_key, description) VALUES ('fuckvb', 'Adds an in-game selector for alternate weapon-overclock configurations, with Heavy Hitter, SCC, Overdrive, Oversized, Flechettes, Hyper, and vanilla modes.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('cave', 'Reworks procedural cave generation across biomes and missions, changing room-query choices, tunnel-noise settings, terrain generation, and extraction layouts.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('novaksenemymiscellanea', 'Adds assorted enemy variants and behavior assets, including Electrocrystal and leaper enemies, healing orbs, smart rocks, custom projectiles, and Stalker speed effects.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
